var WL_DICT=['cold','cord','core','care','cure','cake','lake','like','lime','line','lion','loan','load','lead','head','heal','tail','tale','time','tile','tide','wide','wife','wine','wind','wand','ward','warm','worm','word','work','park','part','past','post','port','pork','pool','poor','door','boar','bear','beat','boat','boot','root','rook','book','cook','look','lock','lack','luck','duck','dusk','dust','must','mist','most','mast','cast','cost','coat','cart','card','hard','hand','band','bend','bond','bone','born','corn','coin','icon','iron','burn','turn','torn','town','twin','tank','rank','bank','sank','sand','send','son','sun','run','fun','fan','fat','cat','cot','cut','nut','net','pet','pen','pan','pin','pit','pot','pat','rat','rot','tot','ton','tin','tan','ten','men','man','can','cap','cop','top','tip','tap','lap','lip','map','nap','rip','hip','hop','mop','sop','sob','rob','rub','tub','pub','pug','bug','big','bag','bad','bed','red','rod','rid','rid','mad','mud','mug','rug'];
function wordLadder(start, end, dict){
  start=String(start||'').toLowerCase(); end=String(end||'').toLowerCase();
  dict=dict||WL_DICT;
  if(start.length!==end.length) return {ok:false, reason:'length'};
  if(start===end) return {ok:true, path:[start]};
  var set={}; for(var i=0;i<dict.length;i++) set[dict[i]]=1;
  set[start]=1; set[end]=1;
  var prev={}; var q=[start]; prev[start]=null;
  function neighbors(w){ var res=[]; for(var i=0;i<w.length;i++){ for(var c=97;c<=122;c++){ var nw=w.slice(0,i)+String.fromCharCode(c)+w.slice(i+1); if(set[nw] && prev[nw]===undefined && nw!==w) res.push(nw); } } return res; }
  var found=false;
  while(q.length){ var cur=q.shift(); if(cur===end){ found=true; break; } var nb=neighbors(cur); for(var k=0;k<nb.length;k++){ prev[nb[k]]=cur; q.push(nb[k]); } }
  if(!found) return {ok:false, reason:'unreachable'};
  var path=[]; var p=end; while(p!==null){ path.unshift(p); p=prev[p]; }
  return {ok:true, path:path};
}

var EXPORTS={wordLadder:wordLadder};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WordLadderForgePure = EXPORTS; }
